const express = require('express');
const Redis = require('ioredis');
const { verifyUserToken } = require('../auth');
const { db } = require('../db');

const router = express.Router();
const redis = new Redis(process.env.REDIS_URL);

router.get('/api/vehicles/:vin/location/poll', verifyUserToken, async (req, res) => {
  const { vin } = req.params;
  const lastTimestamp = req.query.since || '0';

  const registration = await db.query(
    'SELECT id FROM user_vehicles WHERE vin = $1 AND user_id = $2',
    [vin, req.user.id]
  );
  if (!registration.rows.length) {
    return res.status(403).json({ error: 'Access denied: you do not own this vehicle' });
  }

  const startTime = Date.now();
  while (Date.now() - startTime < 20000) {
    const latestPing = await redis.get(`gps:${vin}:latest`);
    if (latestPing) {
      const parsed = JSON.parse(latestPing);
      if (parsed.timestamp > parseInt(lastTimestamp, 10)) {
        return res.json({ vin, location: parsed });
      }
    }
    await new Promise((r) => setTimeout(r, 1000));
  }

  res.json({ vin, location: null, timeout: true });
});
